<?php get_header(); while(have_posts()): the_post(); ?><article id="post-<?php the_ID(); ?>" <?php post_class('page-shell'); ?>><?php if (!is_front_page() && !is_page('studio-home')): ?><header class="page-heading"><p class="eyebrow"><?php echo esc_html(get_bloginfo('name')); ?> / <?php the_title(); ?></p><h1><?php the_title(); ?><span class="title-dot">.</span></h1></header><?php endif; ?><div class="entry-content"><?php the_content(); wp_link_pages(); ?></div></article><?php endwhile; get_footer(); ?>